784	export function createRibbon(course: Course, opts: { s0: number; s1: number; quality: 'high' | 'low' }): Ribbon {
785	  const { s0, s1, quality } = opts;
786	  const ds = quality === 'high' ? 0.4 : 0.7;
787	  const cols = quality === 'high' ? 18 : 10;
788	  const rows = Math.ceil((s1 - s0) / ds) + 1;
789	  const vertsPerRow = cols + 1 + 2; // + skirt left/right
790	  const n = rows * vertsPerRow;
791	  const pos = new Float32Array(n * 3);
792	  const nor = new Float32Array(n * 3);
793	  const uv = new Float32Array(n * 2);
794	  const halfW = new Float32Array(n);
795	  const speed = new Float32Array(n);
796	  const amp = new Float32Array(n);
797	  const skirt = new Float32Array(n);
798	  const style = new Float32Array(n * 4);
799	  const core = new Float32Array(n);
800	  const tang = new Float32Array(n * 3);
801	  const tmp = new THREE.Vector3();
802	  const nrm = new THREE.Vector3();
803	  let k = 0;
804	  for (let i = 0; i < rows; i++) {
805	    const s = Math.min(s1, s0 + i * ds);
806	    const f = course.sample(s);
807	    const hw = course.widthAt(s) / 2;
808	    const sp = Math.max(3, course.prop(s, 'speed'));
809	    const a = ampAt(course, s);
810	    const bs = bandStyleAt(course, s);
811	    const cl = coreLateral(course, s);
812	    const put = (u: number, lateral: number, h: number, isSkirt: number, nn: THREE.Vector3) => {
813	      tmp.copy(f.pos).addScaledVector(f.right, lateral).addScaledVector(f.up, h);
814	      tmp.toArray(pos, k * 3);
815	      nn.toArray(nor, k * 3);
816	      f.tan.toArray(tang, k * 3);
817	      uv[k * 2] = u;
818	      uv[k * 2 + 1] = s;
819	      halfW[k] = hw;
820	      speed[k] = sp;
821	      amp[k] = a;
822	      skirt[k] = isSkirt;
823	      for (let q = 0; q < 4; q++) style[k * 4 + q] = bs[q];
824	      core[k] = cl;
825	      k++;
826	    };
827	    // left skirt (below left edge)
828	    put(-1, -hw * 1.01, EDGE_LIFT - 0.7, 1, nrm.copy(f.right).negate());
829	    for (let j = 0; j <= cols; j++) {
830	      const u = -1 + (2 * j) / cols;
831	      const lift = EDGE_LIFT * Math.abs(u) ** 3;
832	      const slope = (EDGE_LIFT * 3 * u * Math.abs(u)) / hw; // d lift / d lateral
833	      nrm.copy(f.up).addScaledVector(f.right, -slope).normalize();
834	      put(u, u * hw, lift, 0, nrm);
835	    }
836	    put(1, hw * 1.01, EDGE_LIFT - 0.7, 1, nrm.copy(f.right));
837	  }
838	  const idx: number[] = [];
839	  for (let i = 0; i < rows - 1; i++) {
840	    for (let j = 0; j < vertsPerRow - 1; j++) {
841	      const a = i * vertsPerRow + j, b = a + 1, c = a + vertsPerRow, d = c + 1;
842	      idx.push(a, c, b, b, c, d);
843	    }
844	  }
845	  const geo = new THREE.BufferGeometry();
846	  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
847	  geo.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
848	  geo.setAttribute('aUV', new THREE.BufferAttribute(uv, 2));
849	  geo.setAttribute('aHalfW', new THREE.BufferAttribute(halfW, 1));
850	  geo.setAttribute('aSpeed', new THREE.BufferAttribute(speed, 1));
851	  geo.setAttribute('aAmp', new THREE.BufferAttribute(amp, 1));
852	  geo.setAttribute('aSkirt', new THREE.BufferAttribute(skirt, 1));
853	  geo.setAttribute('aStyle', new THREE.BufferAttribute(style, 4));
854	  geo.setAttribute('aCore', new THREE.BufferAttribute(core, 1));
855	  geo.setAttribute('aTan', new THREE.BufferAttribute(tang, 3));
856	  geo.setIndex(idx);
857	  geo.computeBoundingSphere();
858	
859	  const st03 = course.stage('03'), st04 = course.stage('04'), st08 = course.stage('08');
860	  const uniforms = withFog({
861	    uTime: { value: 0 },
862	    uCyanDeep: { value: RIBBON_PAL.cyanDeep.clone() },
863	    uCyan: { value: RIBBON_PAL.cyan.clone() },
864	    uCyanBright: { value: RIBBON_PAL.cyanBright.clone() },
865	    uPinkDeep: { value: RIBBON_PAL.pinkDeep.clone() },
866	    uPink: { value: RIBBON_PAL.pink.clone() },
867	    uPinkLight: { value: RIBBON_PAL.pinkLight.clone() },
868	    uFoam: { value: PALETTE.foam.clone() },
869	    uFoamLav: { value: PALETTE.foamLav.clone() },
870	    uHaze: { value: PALETTE.haze.clone() },
871	    uLightDir: { value: new THREE.Vector3(0.3, 1.0, 0.45).normalize() },
872	    uBenny: { value: new THREE.Vector3(0, 0, 0) },
873	    uBennyR: { value: 0.7 },
874	    uChevron: { value: new THREE.Vector3(st04.s0 + 8.5, 3.6, 1) },
875	    uOutro: { value: new THREE.Vector2(0, st08.s0) },
876	    uHide: { value: new THREE.Vector4(st03.s0, st04.s0, 0, 0) },
877	    uC5Deep: { value: RIVER05_PAL.cyanDeep.clone() },
878	    uC5: { value: RIVER05_PAL.cyan.clone() },
879	    uC5Bright: { value: RIVER05_PAL.cyanBright.clone() },
880	    uC5Streak: { value: RIVER05_PAL.cyanStreak.clone() },
881	    uP5Deep: { value: RIVER05_PAL.pinkDeep.clone() },
882	    uP5: { value: RIVER05_PAL.pink.clone() },
883	    uP5Light: { value: RIVER05_PAL.pinkLight.clone() },
884	    uP5Streak: { value: RIVER05_PAL.pinkStreak.clone() },
885	    uFlow05: { value: course.stage('05').speed * FLOW05 },
886	  });
887	  const mat = new THREE.ShaderMaterial({
888	    uniforms,
889	    vertexShader: VERT,
890	    fragmentShader: FRAG,
891	    fog: true,
892	    side: THREE.DoubleSide,
893	    defines: quality === 'low' ? { LOW_Q: 1 } : {},
894	  });
895	  const mesh = new THREE.Mesh(geo, mat);
896	  mesh.name = 'water_ribbon';
897	  mesh.frustumCulled = false; // one long mesh spanning the whole course
898	  return {
899	    mesh,
900	    uniforms,
901	    s0,
902	    s1,
903	    heightAt(s, lateral, t) {
904	      const hw = course.widthAt(s) / 2;
905	      return ribbonWave(lateral / hw, s, t, ampAt(course, s));
906	    },
907	  };
908	}
