96	/** the ribbon shader's 05 band S (sbend) */
97	const sbend05 = (s: number) => 1.05 * Math.sin(s * 0.31 - 0.834) + 0.18 * Math.sin(s * 0.62 + 0.6);
98	
99	export interface FarRiverLayout {
100	  row(Z: number): FarRiverRow;
101	  /** half chord of the tube floor at the water level */
102	  chord: number;
103	}
104	
105	/**
106	 * Far design row for a water-body centre xB: the body hugs the outer wall of each bend (half width
107	 * EXTENT_FAR − |xB|); the two pink bands are thin lines near the banks (ref 05 far field: 3–10 px bands, the cyan
108	 * core fills the river), the inner-bank band sits a little further in.
109	 */
110	function designFromXB(xB: number, Z: number): FarRiverRow {
111	  const hw = EXTENT_FAR - Math.sqrt(xB * xB + 0.09);
112	  const bend = Math.min(1, Math.abs(xB) / 2.5);
113	  const aIn = 0.25 + 0.2 * bend, aOut = 0.25 - 0.08 * bend;
114	  const aL = xB >= 0 ? aIn : aOut, aR = xB >= 0 ? aOut : aIn;
115	  const w = Math.min(0.65, Math.max(0.26, 0.13 * hw)) * (1 - 0.35 * smoothstep(60, 200, Z));
116	  const cL = xB - hw * (1 - aL), cR = xB + hw * (1 - aR);
117	  return { xB, hw, cL, wL: w, cR, wR: w, core: 0.5 * (cL + cR) };
118	}
119	
120	/**
121	 * Layout of the far river at virtual depth Z. For small Z it is the REAL ribbon exactly as the eye would see it
122	 * there without the far section: at the seam the route is in its exit bend (heading ≈26° off the axis), so a
123	 * screen row cuts the ribbon diagonally — each band centre / bank edge curve l(s) of the real ribbon is intersected
124	 * with the row (axial = Z), widths divided by cos(heading). It blends (Z 2 → 10) into the designed FAR05_CORE path.
125	 */
126	export function farRiverLayout(course: Course, ft: ForcedTunnel, level: number): FarRiverLayout {
127	  const q = new THREE.Vector3();
128	  const at = (s: number, l: number) => {
129	    const f = course.sample(s);
130	    q.copy(f.pos).addScaledVector(f.right, l).sub(ft.c0);
131	    return { ax: q.dot(ft.T), x: q.dot(ft.Rt), rx: f.right.dot(ft.Rt) };
132	  };
133	  // the real ribbon's band layout at s, relative to the route centre (ribbon frame, vCore = coreLateral)
134	  const relLay = (s: number) => bandLayout(0, course.widthAt(s) / 2, coreLateral(course, s), sbend05(s), s);
135	  const cross = (Z: number, lOf: (s: number) => number) => {
136	    let a = ft.sF - 8, b = ft.sF + 16;
137	    for (let i = 0; i < 36; i++) { const m = 0.5 * (a + b); if (at(m, lOf(m)).ax < Z) a = m; else b = m; }
138	    const s = 0.5 * (a + b), p = at(s, lOf(s));
139	    return { s, x: p.x, rx: Math.max(0.3, p.rx) };
140	  };
141	  const realRow = (Z: number): FarRiverRow => {
142	    const eL = cross(Z, (s) => -course.widthAt(s) / 2), eR = cross(Z, (s) => course.widthAt(s) / 2);
143	    const bl = cross(Z, (s) => relLay(s).cL), br = cross(Z, (s) => relLay(s).cR);
144	    const wL = relLay(bl.s).wL / bl.rx, wR = relLay(br.s).wR / br.rx;
145	    return { xB: 0.5 * (eL.x + eR.x), hw: 0.5 * (eR.x - eL.x), cL: bl.x, wL, cR: br.x, wR, core: 0.5 * (bl.x + wL + br.x - wR) };
146	  };
147	  const designRow = (Z: number): FarRiverRow => {
148	    const target = hermite(FAR05_CORE, Z);
149	    let a = -5, b = 5;
150	    for (let i = 0; i < 36; i++) { const m = 0.5 * (a + b); if (designFromXB(m, Z).core < target) a = m; else b = m; }
151	    return designFromXB(0.5 * (a + b), Z);
152	  };
153	  const chord = Math.sqrt(Math.max(0, ft.R * ft.R - level * level)) * 0.995;
154	  return {
155	    chord,
156	    row(Z) {
157	      const w = smoothstep(2, 10, Z);
158	      if (w <= 0) return realRow(Z);
159	      const d = designRow(Z);
160	      if (w >= 1) return d;
161	      const r = realRow(Math.min(Z, 8));
162	      const o = {} as FarRiverRow;
163	      for (const k of Object.keys(d) as (keyof FarRiverRow)[]) o[k] = r[k] + (d[k] - r[k]) * w;
164	      return o;
165	    },
166	  };
167	}
168	
169	/**
170	 * The far river surface in the virtual tunnel: one row per screen step (uniform in 1/depth, like the far wall),
171	 * spanning the whole tube floor chord at `level` so it covers the real ribbon's continuation behind the seam.
172	 * Columns: 3 over each bank, `cols` over the water body (whose centre/width change per row); the body has the
173	 * ribbon's trough profile (EDGE_LIFT·|u|³) so it lands on the real ribbon at the seam, the banks sit a little
174	 * higher (foam rims). Attributes for farRiverMaterial: aRivLat (lateral, units from the axis), aRivA (xB, hw,
175	 * cL, cR), aRivB (wL, wR, core, Z), fgExtra (virtual − real depth). Morph "open": dropped below the real tube
176	 * bottom (as the old chord), so the ride into 06 is untouched.
177	 */
178	export function farRiverGeometry(ft: ForcedTunnel, lay: FarRiverLayout, level: number, cols = 16, steps = 120): THREE.BufferGeometry {
179	  const bank = 3;
180	  const per = cols + 1 + 2 * bank;
181	  const rows = steps + 1;
182	  const n = rows * per;
183	  const pos = new Float32Array(n * 3), nor = new Float32Array(n * 3), uv = new Float32Array(n * 2);
184	  const lat = new Float32Array(n), A = new Float32Array(n * 4), B = new Float32Array(n * 4), ext = new Float32Array(n), opn = new Float32Array(n * 3);
185	  const o = new THREE.Vector3(), p = new THREE.Vector3(), cr = new THREE.Vector3();
186	  const ch = lay.chord;
187	  for (let i = 0; i < rows; i++) {
188	    const t = i / steps;
189	    const Dv = 1 / (1 / ft.D0 - t * (1 / ft.D0 - 1 / (ft.D0 + ft.zEnd)));
190	    const Z = Math.max(0, Dv - ft.D0);
191	    const z = ft.zOf(Z);
192	    const sReal = ft.sF + z;
193	    const fr = ft.path.frame(sReal);
194	    tubeCenterAt(ft.path, sReal, cr);
195	    const rr = ft.path.radius(sReal);
196	    const r = lay.row(Z);
197	    const e0 = Math.max(-ch + 0.05, r.xB - r.hw), e1 = Math.min(ch - 0.05, r.xB + r.hw);
198	    for (let j = 0; j < per; j++) {
199	      let x: number, h: number;
200	      if (j < bank) { const f = j / bank; x = -ch + (e0 + ch) * f; h = EDGE_LIFT + 0.1 * Math.sin(Math.PI * f); }
201	      else if (j > bank + cols) { const f = (j - bank - cols) / bank; x = e1 + (ch - e1) * f; h = EDGE_LIFT + 0.1 * Math.sin(Math.PI * f); }
202	      else {
203	        const f = (j - bank) / cols; x = e0 + (e1 - e0) * f;
204	        const u = Math.min(1, Math.abs(x - r.xB) / Math.max(0.5, r.hw));
205	        h = EDGE_LIFT * u * u * u;
206	      }
207	      o.copy(ft.Rt).multiplyScalar(x).addScaledVector(ft.U, level + h);
208	      ft.point(Z, o, p);
209	      const k = i * per + j;
210	      p.toArray(pos, k * 3);
211	      ft.U.toArray(nor, k * 3);
212	      uv[k * 2] = (x + ch) / (2 * ch); uv[k * 2 + 1] = ft.sF + ft.uOfZ(Z);
213	      lat[k] = x;
214	      A[k * 4] = r.xB; A[k * 4 + 1] = r.hw; A[k * 4 + 2] = r.cL; A[k * 4 + 3] = r.cR;
215	      B[k * 4] = r.wL; B[k * 4 + 1] = r.wR; B[k * 4 + 2] = r.core; B[k * 4 + 3] = Z;
216	      ext[k] = Z - z;
217	      o.copy(cr).addScaledVector(fr.right, x * (rr / ft.R)).addScaledVector(fr.up, -rr - 0.6);
218	      o.toArray(opn, k * 3);
219	    }
220	  }
221	  const idx: number[] = [];
222	  for (let i = 0; i < rows - 1; i++) {
223	    for (let j = 0; j < per - 1; j++) {
224	      const a = i * per + j, b = a + per;
225	      idx.push(a, a + 1, b, b, a + 1, b + 1);
226	    }
227	  }
228	  const g = new THREE.BufferGeometry();
229	  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
230	  g.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
231	  g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
232	  g.setAttribute('aRivLat', new THREE.BufferAttribute(lat, 1));
233	  g.setAttribute('aRivA', new THREE.BufferAttribute(A, 4));
234	  g.setAttribute('aRivB', new THREE.BufferAttribute(B, 4));
235	  g.setAttribute('fgExtra', new THREE.BufferAttribute(ext, 1));
236	  g.morphAttributes.position = [new THREE.BufferAttribute(opn, 3)];
237	  g.setIndex(idx);
238	  g.computeBoundingSphere();
239	  return g;
240	}
