710	let marbleEnv05: THREE.Texture | null = null;
711	export function marblePano05(): THREE.Texture {
712	  if (marbleEnv05) return marbleEnv05;
713	  // three's UUIDs draw on Math.random: keep the global sequence untouched so the random canvas textures built
714	  // later (08 laundry room, pour streams) stay pixel-identical, and give the texture a fixed uuid instead
715	  const rnd = Math.random;
716	  Math.random = () => 0.5;
717	  let t: THREE.Texture;
