730	/** envMapRotation that puts the pano's vanishing point (u 0.514, v 0.542 in three's equirect uv) on the
731	 *  tunnel direction `tan` (and the pano's up on world up) */
732	export function marblePanoRotation05(tan: THREE.Vector3): THREE.Euler {
733	  const az = (0.514 - 0.5) * Math.PI * 2, el = (0.542 - 0.5) * Math.PI;
734	  const P = new THREE.Vector3(Math.cos(el) * Math.cos(az), Math.sin(el), Math.cos(el) * Math.sin(az));
735	  const basis = (f: THREE.Vector3) => {
736	    const u = new THREE.Vector3(0, 1, 0).addScaledVector(f, -f.y).normalize();
737	    return new THREE.Matrix4().makeBasis(f.clone().normalize(), u, new THREE.Vector3().crossVectors(f, u).normalize());
738	  };
739	  const W = basis(tan), Q = basis(P);
740	  const M = Q.multiply(W.transpose()); // world direction → pano lookup direction
741	  const e = new THREE.Euler().setFromRotationMatrix(M, 'XYZ');
742	  // three applies makeRotationFromEuler(−rotation) to the lookup vector (WebGLMaterials, PMREM env)
743	  return new THREE.Euler(-e.x, -e.y, -e.z, 'XYZ');
744	}
